/* Preserved source-language editorial pages, integrated into visitor pathways. */
const V3_EDITION_TITLES={'studienkolleg':['Studienkolleg Aachen','Studienkolleg Aachen'],'course-T':['T-Kurs','T course'],'course-M':['M-Kurs','M course'],'course-W':['W-Kurs','W course'],'course-TM':['Kombinierter M/T-Kurs','Combined M/T course'],'services':['Unterstützung für deinen Weg','Support for your pathway'],'studienkolleg-ablauf-termine':['Dein Weg durchs Studienkolleg','Your Studienkolleg journey'],'apply':['Bewerbung vorbereiten','Prepare your application'],'impressum':['Kontakt & Unternehmensangaben','Contact & company information'],'contact':['Kontakt zum Studienkolleg','Contact Studienkolleg'],'agb':['Vertragsinformationen','Contract information'],'datenschutz':['Datenschutzinformationen','Privacy information']};
const editionLabel=f=>t(...(V3_EDITION_TITLES[f]||[f,f]));
const languageLabels={de:'Deutsch',en:'English',fr:'Français',es:'Español',uk:'Українська',ru:'Русский'};
function v3EditionLinks(target){const versions=MIGRATED_EDITIONS.filter(x=>x.target===target);if(!versions.length)return '';const list=[...new Map(versions.map(x=>[x.locale,x])).values()];return `<section class="v3-language-editions"><h3>${t('Informationen in deiner Sprache','Information in your language')}</h3><p>${t('Lies die vorhandenen Sprachfassungen zu diesem Thema.','Read the existing language editions for this topic.')}</p><div>${list.map(x=>`<a href="#/informationen/${x.id}" lang="${x.locale}">${languageLabels[x.locale]||x.locale}${arrow}</a>`).join('')}</div></section>`}
function v3EditionPage(r){if(r==='/informationen'){const families=[...new Set(MIGRATED_EDITIONS.map(x=>x.family))];return `<section class="v3-page-intro"><span class="eyebrow">${t('INFORMATIONEN IN DEINER SPRACHE','INFORMATION IN YOUR LANGUAGE')}</span><h1>${t('Dein Weg.<br>In vertrauten Worten.','Your pathway.<br>In familiar words.')}</h1><p>${t('Vorhandene Sprachfassungen zu Kursen, Bewerbung, Unterstützung und Studienablauf.','Existing language editions about programmes, applications, support and your study journey.')}</p></section><section class="v3-section"><div class="v3-card-grid two">${families.map(f=>{const group=MIGRATED_EDITIONS.filter(x=>x.family===f);return `<article class="v3-card"><div><h3>${editionLabel(f)}</h3><div class="v3-language-pills">${[...new Map(group.map(x=>[x.locale,x])).values()].map(x=>`<a href="#/informationen/${x.id}" lang="${x.locale}">${languageLabels[x.locale]}</a>`).join('')}</div></div></article>`}).join('')}</div></section>`}const e=MIGRATED_EDITIONS.find(x=>x.id===r.split('/')[2]);if(!e)return notFound();const commercial=e.blocks.filter(x=>/[€$]|\bEUR\b/.test(x.text)),body=e.blocks.filter(x=>!commercial.includes(x));const editionDisclaimer=t('Sprachfassung der bisherigen Website · erfasst am 30.10.2026. Preis-, Termin- und Vertragsangaben bitte aktuell bestätigen lassen.','Language edition from the existing website · captured 30 Oct 2026. Please reconfirm price, date and contractual information.');return `<div class="v3-breadcrumb"><a href="#/informationen">${t('Sprachinformationen','Language information')}</a> / ${languageLabels[e.locale]}</div><section class="v3-page-intro"><span class="eyebrow">${languageLabels[e.locale]} · STUDIENKOLLEG AACHEN</span><h1>${editionLabel(e.family)}</h1><p>${editionDisclaimer}</p></section><section class="v3-section v3-article v3-edition-text" lang="${e.locale}">${v3EditionBlocks(body)}${commercial.length?`<details class="v3-faq v3-published-prices"><summary>${t('Bisher veröffentlichte Preisangaben','Previously published price information')}</summary><p>${t('Diese Angaben stammen aus der jeweiligen Bestandsfassung und sind kein aktuelles Angebot. Andere Quellfassungen nennen abweichende Preise; verbindliche Konditionen bitte bestätigen lassen.','These figures come from this existing edition and are not a current offer. Other source versions show different prices; please confirm binding terms.')}</p>${commercial.map(x=>`<p>${esc(x.text)}</p>`).join('')}</details>`:''}<div class="actions">${link(t('Zum passenden nächsten Schritt','Continue to your next step'),e.target==='/impressum'?'/kontakt':e.target==='/studienkolleg/ablauf-termine'?'/admission':e.target,'secondary')}${link(t('Persönlich beraten lassen','Get personal guidance'),'/beratung')}</div><p class="v3-source-note"><a href="${e.source}" target="_blank" rel="noopener">${t('Veröffentlichte Sprachfassung','Published language edition')}</a> · ${languageLabels[e.locale]} · 30.10.2026</p></section>`}
function v3Timeline(){const stages=[['Bewerbung','Application','Bildungsweg, Kursinteresse und Nachweise zusammenstellen.','Gather your education history, course preference and evidence.'],['Start im Studienkolleg','Start Studienkolleg','Einstieg und persönlichen Stundenplan klären.','Confirm your entry point and individual timetable.'],['Sprachnachweis','Language evidence','Benötigte Sprachprüfung und Vorbereitung abstimmen.','Agree the required language exam and preparation.'],['FSP-Anmeldung','Assessment exam registration','Anmeldeweg, Unterlagen und Frist gesondert bestätigen.','Separately confirm registration, documents and deadline.'],['Zweites Semester','Second semester','Fachliche Vorbereitung fortführen.','Continue subject preparation.'],['Vor- und Zwischenprüfung','Preparatory and intermediate assessment','Lernstand einschätzen und weitere Vorbereitung planen.','Review learning progress and plan further preparation.'],['Feststellungsprüfung','Assessment examination','Den vorgesehenen Prüfungsweg abschließen.','Complete the intended examination pathway.'],['Hochschulbewerbung','University application','Jeden Studienwunsch mit eigener Unterlagenliste und Frist planen.','Plan each study choice with its own documents and deadline.'],['Studienbeginn','University start','Zulassung und Immatrikulation als eigene Schritte vorbereiten.','Prepare admission and enrolment as separate steps.']];return `<section class="v3-page-intro"><span class="eyebrow">${t('DEIN STUDIENWEG','YOUR STUDY PATHWAY')}</span><h1>${t('Von der Bewerbung<br>bis zum Studienbeginn.','From application<br>to university.')}</h1><p>${t('Die Meilensteine helfen dir bei der Orientierung. Deinen konkreten Semester- und Prüfungsplan bestätigt die Beratung.','These milestones help you plan. The advisory team confirms your specific semester and examination schedule.')}</p></section><section class="v3-section"><div class="v3-timeline">${stages.map(([de,en,dd,ee],i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${t(de,en)}</h3><p>${t(dd,ee)}</p></div></article>`).join('')}</div>${link(t('Meinen Einstieg besprechen','Discuss my starting point'),'/beratung')}${v3EditionLinks('/studienkolleg/ablauf-termine')}</section>`}
function v3SupportDetail(r){const recognition=r.endsWith('anerkennung');return `<section class="v3-page-intro"><span class="eyebrow">${t('PERSÖNLICHE UNTERSTÜTZUNG','PERSONAL SUPPORT')}</span><h1>${recognition?t('Deine Vorbildung.<br>Dein nächster Bildungsweg.','Your qualifications.<br>Your next educational pathway.'):t('Gut ankommen.<br>In Verbindung bleiben.','Settle in.<br>Stay connected.')}</h1><p>${recognition?t('Zeugnisse, Übersetzungen und offene Fragen geordnet für die persönliche Beratung vorbereiten.','Organise academic records, translations and open questions for personal guidance.'):t('Persönliche Ansprechpersonen und Orientierungshilfen für deinen Start in Aachen.','Personal contacts and orientation for your start in Aachen.')}</p></section>${v3Section(t('SO KANNST DU STARTEN','HOW TO BEGIN'),recognition?t('Unterlagen verständlich zusammenstellen.','Organise your documents clearly.'):t('Was beschäftigt dich gerade?','What is on your mind?'),`<div class="v3-card-grid two">${v3Card(recognition?t('Dein Bildungsweg','Your education history'):t('Dein Onboarding','Your onboarding'),recognition?t('Schulabschluss, Notenübersicht und vorhandene Nachweise vorbereiten.','Prepare school qualifications, transcripts and existing evidence.'):t('Sprich über deinen Stundenplan, Ankunft und die ersten Fragen im Alltag.','Discuss your timetable, arrival and first everyday questions.'),recognition?'/apply':'/beratung')}${v3Card(recognition?t('Individuelle Fragen klären','Clarify individual questions'):t('Deine Ansprechpersonen','Your contacts'),recognition?t('Anerkennung und Hochschulzugang hängen vom konkreten Abschluss und der zuständigen Stelle ab.','Recognition and university entry depend on your qualification and the responsible organisation.'):t('Vereinbare ein persönliches Gespräch, wenn du Unterstützung beim Ankommen brauchst.','Arrange a personal conversation if you need help settling in.'),'/beratung')}</div><p class="v3-source-note">${t('Unterstützungsbereiche der bestehenden Studienkolleg-Website. Anerkennungen und behördliche Entscheidungen werden nicht durch die Vorschau erteilt.','Support areas from the existing Studienkolleg website. This preview does not grant recognition or official decisions.')}</p>${v3EditionLinks('/services')}`)}`}
function v3Media(){return `<section class="v3-page-intro"><span class="eyebrow">${t('EINBLICKE','INSIGHTS')}</span><h1>${t('Studienkolleg in Bewegung.','Studienkolleg in motion.')}</h1><p>${t('Kurse, Menschen und Alltag: Videos aus dem bestehenden Webauftritt.','Courses, people and everyday life: videos from the existing website.')}</p></section><section class="v3-section"><div class="v3-video-grid">${MIGRATED_MEDIA.map(v=>`<article><button data-v3-media="${v.id}" aria-label="${t('Video öffnen: ','Open video: ')+t(...v.title)}">${v.poster?`<img src="${v.poster}" alt="${esc(t(...v.title))}" loading="lazy">`:`<span class="v3-video-placeholder">${t(...v.title)}</span>`}<span class="v3-play">▶</span></button><h3>${t(...v.title)}</h3></article>`).join('')}</div><p class="v3-source-note">${t('Beim Öffnen eines Videos wird die Mediendatei von deinstudienkolleg.de geladen. Einzelne Originaldateien können aktuell nicht erreichbar sein.','Opening a video loads its media file from deinstudienkolleg.de. Individual original files may currently be unavailable.')}</p></section>`}
const beforeMigrationBody=v3Body;v3Body=function(r){if(r.startsWith('/informationen'))return v3EditionPage(r);if(r==='/studienkolleg/ablauf-termine')return v3Timeline();if(['/services/anerkennung','/services/mentoring'].includes(r))return v3SupportDetail(r);if(r==='/campus/videos')return v3Media();let html=beforeMigrationBody(r);if(['/course/T','/course/M','/course/W','/course/TM','/services','/kontakt','/apply'].includes(r))html+=v3EditionLinks(r==='/kontakt'?'/contact':r);if(r==='/services')html+=v3Section(t('WEITERE UNTERSTÜTZUNG','MORE SUPPORT'),t('Auch jenseits des Unterrichts.','Beyond the classroom.'),`<div class="v3-card-grid two">${v3Card(t('Zeugnisanerkennung','Qualification recognition'),t('Vorbildung und Nachweise für deinen nächsten Weg klären.','Clarify your qualifications and evidence for the next step.'),'/services/anerkennung')}${v3Card(t('Mentoring & Wohlbefinden','Mentoring & wellbeing'),t('Ankommen, Fragen stellen und persönliche Unterstützung finden.','Settle in, ask questions and find personal support.'),'/services/mentoring')}</div>`);if(r==='/campus'||r==='/')html+=v3Section(t('MENSCHEN & MOMENTE','PEOPLE & MOMENTS'),t('Entdecke das Studienkolleg in Videos.','Explore Studienkolleg through video.'),`<p>${t('Kurse kennenlernen, Stimmen aus der Gemeinschaft hören und einen Blick in den Alltag werfen.','Explore courses, hear from the community and get a glimpse of everyday life.')}</p>${link(t('Videos ansehen','Watch videos'),'/campus/videos','secondary')}`);return html};
const beforeMigrationBind=v3Bind;v3Bind=function(){beforeMigrationBind();document.querySelectorAll('[data-v3-media]').forEach(e=>e.addEventListener('click',()=>{const v=MIGRATED_MEDIA.find(x=>x.id===e.dataset.v3Media);vModal(t(...v.title),`<video controls preload="none" ${v.poster?`poster="${v.poster}"`:''} style="width:100%;max-height:65vh" src="${v.src}">${t('Dieses Video kann im Browser nicht wiedergegeben werden.','This video cannot be played in this browser.')}</video><p class="v3-source-note">${t('Originalvideo der bestehenden Website. Falls die Datei nicht erreichbar ist, öffne den ursprünglichen Webauftritt.','Original video from the existing website. If the file is unavailable, open the original website.')} <a href="https://deinstudienkolleg.de/" target="_blank" rel="noopener">${t('Original-Website','Original website')}</a></p>`)}))};
render();
const V3_BOOKING={step:0,type:'Erstberatung',name:'',email:'',phone:'',date:'2026-11-03',time:'10:00',confirmed:false};
function bookingTypeLabel(value){const labels={'Erstberatung':['Erstberatung','Initial guidance'],'Kursberatung':['Kursberatung','Course guidance'],'Prüfungsberatung':['Prüfungsberatung','Exam guidance'],'Bewerbungsgespräch':['Bewerbungsgespräch','Application conversation']};return Object.prototype.hasOwnProperty.call(labels,value)?t(...labels[value]):String(value||'')}
function v3Booking(){const b=V3_BOOKING;return `<section class="v3-page-intro"><span class="eyebrow">${t('PERSÖNLICHE BERATUNG','PERSONAL GUIDANCE')}</span><h1>${t('Deine Fragen verdienen<br>ein persönliches Gespräch.','Your questions deserve<br>a personal conversation.')}</h1><p>${t('Wähle dein Anliegen und bereite deinen Wunschtermin vor.','Choose your topic and prepare your preferred appointment.')}</p></section><section class="v3-section"><div class="v3-booking-flow"><nav class="v3-booking-steps" aria-label="${t('Beratungsschritte','Guidance steps')}">${[t('Anliegen & Kontakt','Topic & contact'),t('Wunschtermin','Preferred time'),t('Übersicht','Review')].map((l,i)=>`<span class="${b.step===i?'current':''}"><b>${i+1}</b>${l}</span>`).join('')}</nav>${b.confirmed?`<div class="v3-success"><h2>${t('Deine Auswahl ist vorbereitet.','Your selection is ready.')}</h2><p>${t('In dieser Vorschau wurde kein Termin gebucht und keine Nachricht versendet. Für ein echtes Gespräch nutze den veröffentlichten Kontaktweg.','This preview has not booked an appointment or sent a message. Use the published contact channel for a real conversation.')}</p><p><strong>${esc(bookingTypeLabel(b.type))}</strong><br>${esc(b.date)} · ${esc(b.time)}</p><a class="btn" href="https://deinstudienkolleg.de/booking" target="_blank" rel="noopener">${t('Zur bestehenden Terminseite','Open the existing booking page')}${arrow}</a></div>`:`<form id="v3-booking-form"><span class="v3-local-label">${t('Formularvorschau · nur Beispieldaten · keine echten Zeitfenster','Form preview · sample details only · not real appointment availability')}</span>${b.step===0?`<h2>${t('Worum geht es dir?','What would you like to discuss?')}</h2><div class="v3-booking-types">${[['Erstberatung','Initial guidance'],['Kursberatung','Course guidance'],['Prüfungsberatung','Exam guidance'],['Bewerbungsgespräch','Application conversation']].map(([de,en])=>`<label><input name="booking-type" type="radio" value="${de}" ${b.type===de?'checked':''}><span>${t(de,en)}</span></label>`).join('')}</div><div class="form-grid"><label class="field">${t('Vollständiger Name','Full name')}<input id="booking-name" required value="${esc(b.name)}" placeholder="Alex Beispiel" autocomplete="off"></label><label class="field">${t('E-Mail','Email')}<input id="booking-email" required type="email" value="${esc(b.email)}" placeholder="alex@example.com" autocomplete="off"></label><label class="field">${t('Telefon (optional)','Phone (optional)')}<input id="booking-phone" value="${esc(b.phone)}" placeholder="${t('Nur Beispieldaten','Sample data only')}" autocomplete="off"></label></div>`:b.step===1?`<h2>${t('Wann passt es dir?','When would suit you?')}</h2><div class="form-grid"><label class="field">${t('Wunschdatum · Beispiel','Preferred date · sample')}<input id="booking-date" type="date" value="${b.date}" required></label><label class="field">${t('Uhrzeit · Beispiel','Preferred time · sample')}<select id="booking-time">${['09:00','10:00','14:30','16:00'].map(v=>`<option ${b.time===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p>${t('Die bestehenden Kontaktinformationen nennen Montag bis Freitag, 09:00–17:00 Uhr. Diese Auswahl zeigt keine echte Kalenderverfügbarkeit.','The existing contact information lists Monday to Friday, 09:00–17:00. This selection does not show real calendar availability.')}</p>`:`<h2>${t('Deine Auswahl im Überblick.','Review your selection.')}</h2><dl class="v3-facts"><div><dt>${t('Anliegen','Topic')}</dt><dd>${esc(bookingTypeLabel(b.type))}</dd></div><div><dt>${t('Wunschzeit','Preferred time')}</dt><dd>${esc(b.date)} · ${esc(b.time)}</dd></div><div><dt>${t('Beispielname','Sample name')}</dt><dd>${esc(b.name)}</dd></div><div><dt>${t('Beispielkontakt','Sample contact')}</dt><dd>${esc(b.email)}</dd></div></dl><p><strong>${t('Es wird nichts versendet oder gebucht.','Nothing will be sent or booked.')}</strong> ${t('Du bestätigst ausschließlich deine Auswahl in dieser Vorschau.','You are confirming your selection in this preview only.')}</p>`}<div class="actions">${b.step?`<button type="button" class="btn secondary" data-v3-booking-back>${t('Zurück','Back')}</button>`:''}<button class="btn" type="submit">${b.step===2?t('Auswahl bestätigen','Confirm selection'):t('Weiter','Continue')}${arrow}</button></div></form>`}</div><div class="v3-contact-strip"><a href="tel:+4924199032292">+49 241 990 322 92</a><a href="mailto:info@stk-aachen.de">info@stk-aachen.de</a><a href="https://maps.google.com/?q=Theaterstra%C3%9Fe+30-32,+52062+Aachen" target="_blank" rel="noopener">Theaterstraße 30–32 · Aachen ↗</a></div></section>`}
const beforeBookingBody=v3Body;v3Body=function(r){if(r==='/beratung'||r==='/booking')return v3Booking();let html=beforeBookingBody(r);if(r==='/kontakt'||r==='/contact')html+=v3Section(t('DIREKT IN VERBINDUNG','DIRECT CONTACT'),t('Finde deinen Kontaktweg.','Find your contact channel.'),`<p><strong>${t('Sprechzeiten laut bestehender Website:','Published contact hours:')}</strong> ${t('Montag–Freitag, 09:00–17:00 Uhr.','Monday–Friday, 09:00–17:00.')}</p><div class="actions"><a class="btn secondary" href="https://wa.me/4915208496876" target="_blank" rel="noopener">WhatsApp ↗</a><a class="btn secondary" href="https://deinstudienkolleg.de/contact" target="_blank" rel="noopener">${t('Bestehende Kontaktseite','Existing contact page')} ↗</a>${link(t('Anfrage vorbereiten','Prepare an enquiry'),'/beratung')}</div>`);return html};
const beforeBookingBind=v3Bind;v3Bind=function(){beforeBookingBind();document.querySelector('[data-v3-booking-back]')?.addEventListener('click',()=>{V3_BOOKING.step=Math.max(0,V3_BOOKING.step-1);render()});document.getElementById('v3-booking-form')?.addEventListener('submit',e=>{e.preventDefault();const b=V3_BOOKING;if(b.step===0){b.type=document.querySelector('[name="booking-type"]:checked').value;b.name=document.getElementById('booking-name').value;b.email=document.getElementById('booking-email').value;b.phone=document.getElementById('booking-phone').value;}if(b.step===1){b.date=document.getElementById('booking-date').value;b.time=document.getElementById('booking-time').value;}if(b.step===2)b.confirmed=true;else b.step++;render()})};
const baseApplicationV3=application;application=function(){let html=baseApplicationV3();if(!state.submitted&&state.step===0)html=html.replace('<label class="field">'+t('Zeitliche Orientierung','Preferred timing'),`<label class="field">${t('Land deines letzten Abschlusses (Beispiel)','Country of your last qualification (sample)')}<input data-v3-education-country value="${esc(state.application.educationCountry||'')}" placeholder="${t('Zum Beispiel: Indien','For example: India')}"></label><label class="field">`+t('Zeitliche Orientierung','Preferred timing'));if(!state.submitted&&state.step===1)html=html.replace('<div class="actions" style="justify-content:space-between">',`<div class="file-row"><div class="file-main"><span class="file-icon">ID</span><div><strong>${t('Reisepass · ergänzender Nachweis','Passport · supplementary evidence')}</strong><small>${state.application.passport?t('Muster ergänzt · Prüfung offen','Sample added · review pending'):t('Zusätzlicher Nachweis aus dem bisherigen Bewerbungsformular','Additional evidence from the existing application form')}</small></div></div><button class="btn small secondary" data-v3-passport>${state.application.passport?t('Muster ergänzt','Sample added'):t('Musternachweis ergänzen','Add sample evidence')}</button></div><div class="actions" style="justify-content:space-between">`);return html};
const beforePassportBind=v3Bind;v3Bind=function(){beforePassportBind();document.querySelector('[data-v3-education-country]')?.addEventListener('input',e=>state.application.educationCountry=e.target.value);document.querySelector('[data-v3-passport]')?.addEventListener('click',()=>{state.application.passport=true;render()})};
const priorFooterV3=v3Footer;v3Footer=function(){return priorFooterV3().replace('<div class="v3-footer-bottom">',`<div class="v3-social-links"><a href="https://www.instagram.com/carpediem_studienkolleg/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.facebook.com/studienkollegaachen" target="_blank" rel="noopener">Facebook ↗</a><a href="https://www.youtube.com/@StudienkollegAachen" target="_blank" rel="noopener">YouTube ↗</a><a href="#/informationen">${t('Informationen in deiner Sprache','Information in your language')}</a></div><div class="v3-footer-bottom">`)};
render();
const completeHousingDetail=v3HousingDetail;v3HousingDetail=function(h){let html=completeHousingDetail(h);const map=h.map?`<a class="btn secondary" href="${esc(h.map)}" target="_blank" rel="noopener">${t('Lage auf der Karte ansehen','View location on the map')}${arrow}</a>`:'';return html+v3Section(t('DEIN EINZUG','YOUR MOVE-IN'),t('Persönlich abstimmen. Gut ankommen.','Make arrangements. Settle in.'),`<p>${t('Besichtigung, Vertragsfragen und Schlüsselübergabe werden persönlich vereinbart. Teile deinen gewünschten Einzug frühzeitig mit. Küche, Arbeitsbereich, möbliertes Bett und Badezimmer gehören zur veröffentlichten Beschreibung.','Viewings, contract questions and key handover are arranged personally. Share your preferred move-in date in advance. The published description includes a kitchen, study area, furnished bed and bathroom.')}</p><div class="actions">${map}<a class="btn secondary" href="mailto:info@stayinaachen.de">info@stayinaachen.de</a></div><p class="v3-source-note">${t('Kontakt der veröffentlichten Wohnungsseite. Eine Anfrage ist noch kein Mietvertrag.','Contact from the published housing website. An enquiry is not a rental contract.')}</p>`)};
const fullHousingEnquiry=v3HousingEnquiry;v3HousingEnquiry=function(r){let html=fullHousingEnquiry(r);html=html.replace('<label class="field">'+t('E-Mail','Email'),`<label class="field">${t('Nachname','Last name')}<input required placeholder="Beispiel" name="last" autocomplete="off"></label><label class="field">`+t('E-Mail','Email'));html=html.replace('<label class="field">'+t('Deine Nachricht','Your message'),`<label class="field">${t('Wie hast du uns gefunden?','How did you hear about us?')}<select><option>${t('Bitte auswählen (optional)','Choose an option (optional)')}</option><option>Google Search</option><option>Social Media</option><option>${t('Freunde oder Familie','Friends or family')}</option><option>${t('Werbung','Advertisement')}</option><option>${t('Sonstiges','Other')}</option></select></label><label class="field">`+t('Deine Nachricht','Your message'));return html+`<div class="v3-contact-strip" style="margin:0 24px 32px"><a href="mailto:info@stayinaachen.de">info@stayinaachen.de</a><a href="tel:+4924199032292">+49 241 990 322 92</a><a href="https://stayinaachen.de/contact-us-draft/" target="_blank" rel="noopener">${t('Bestehende Wohnungs-Kontaktseite','Existing housing contact page')} ↗</a></div>`};
render();

function v3EditionBlocks(blocks){let html='';for(let i=0;i<blocks.length;i++){const b=blocks[i],next=blocks[i+1],value=b.text;if(/^(Gebühren|Fees|Frais|Стоимость|Вартість|Tarifas)[:：]?$/i.test(value))continue;if(value.endsWith(':')&&value.length<65&&next&&next.text.length<150&&!next.text.endsWith(':')){html+=`<dl class="v3-editorial-fact"><dt>${esc(value)}</dt><dd>${esc(next.text)}</dd></dl>`;i++;continue}if(b.type==='li'){html+=`<p class="v3-source-bullet">${esc(value)}</p>`;continue}const heading=b.type.startsWith('h')||(i===0&&value.endsWith(':'))||(value.length<65&&!/[.!?\d@]/.test(value)&&next&&next.text.length>100);html+=heading?`<h2 class="v3-editorial-heading">${esc(value)}</h2>`:`<p>${esc(value)}</p>`;}return html;}

// Focus only explicit application-step transitions, never ordinary edits/uploads.
const beforeApplicationKeyboardAction=action;
action=function(name,value){const applies=route().split('?')[0]==='/apply'&&['next','back','step','complete','edit-application'].includes(name);beforeApplicationKeyboardAction(name,value);if(applies){const main=document.getElementById('main');const target=main?.querySelector('.panel > h3')||main?.querySelector('h1')||main;target?.setAttribute?.('tabindex','-1');target?.focus();}};
